def sha256(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def git_blob(raw: bytes) -> str:
    header = b"blob " + str(len(raw)).encode("ascii") + b"\0"
    return hashlib.sha1(header + raw).hexdigest()


def identity_ok(identity: Mapping[str, object], raw: bytes) -> bool:
    return (
        set(identity) == {"path", "git_blob_sha1", "size_bytes", "raw_sha256", "base64"}
        and type(identity["path"]) is str
        and re.fullmatch(r"[0-9a-f]{40}", str(identity["git_blob_sha1"])) is not None
        and type(identity["size_bytes"]) is int
        and re.fullmatch(r"[0-9a-f]{64}", str(identity["raw_sha256"])) is not None
        and type(identity["base64"]) is str
        and len(raw) == identity["size_bytes"]
        and git_blob(raw) == identity["git_blob_sha1"]
        and sha256(raw) == identity["raw_sha256"]
    )


def clean_git_environment() -> dict[str, str]:
    environment = dict(os.environ)
    for key in tuple(environment):
        if key.startswith("GIT_"):
            del environment[key]
    environment["GIT_TERMINAL_PROMPT"] = "0"
    environment["GIT_NO_LAZY_FETCH"] = "1"
    return environment


def run_git(
    arguments: list[str],
    *,
    stdin: Optional[bytes] = None,
    expected: tuple[int, ...] = (0,),
) -> subprocess.CompletedProcess[bytes]:
    result = subprocess.run(
        arguments,
        input=stdin,
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        env=clean_git_environment(),
    )
    if result.returncode not in expected:
        raise PermissionError("H27 exact receiver Git operation failed.")
    return result


def source_git(
    arguments: list[str],
    *,
    stdin: Optional[bytes] = None,
    expected: tuple[int, ...] = (0,),
) -> subprocess.CompletedProcess[bytes]:
    return run_git(
        [
            "git", "--no-optional-locks", "--no-replace-objects",
            f"--git-dir={GIT_DATABASE_TEXT}", *arguments,
        ],
        stdin=stdin,
        expected=expected,
    )


def source_worktree_git(arguments: list[str]) -> subprocess.CompletedProcess[bytes]:
    return run_git([
        "git", "--no-optional-locks", "--no-replace-objects",
        "-c", "core.hooksPath=/dev/null", "-C", CHECKOUT_TEXT, *arguments,
    ])


def require_platform_ack_and_zero_arguments() -> None:
    if sys.platform != "darwin" or len(sys.argv) != 1 or os.environ.get(ACK_ENV) != "1":
        raise PermissionError("H27 exact macOS receiver acknowledgement and zero arguments required.")


def verify_checkout_and_odb_realpaths() -> None:
    objects = GIT_DATABASE / "objects"
    refs = GIT_DATABASE / "refs"
    for path, label in (
        (CHECKOUT, "checkout"),
        (GIT_DATABASE, "Git database"),
        (objects, "objects directory"),
        (refs, "refs directory"),
    ):
        try:
            resolved = path.resolve(strict=True)
        except OSError as exc:
            raise PermissionError(f"H27 exact {label} is unavailable.") from exc
        if resolved != path or path.is_symlink() or not path.is_dir():
            raise PermissionError(f"H27 exact {label} realpath mismatch.")


def require_reference_storage_files() -> None:
    repository_format = source_git(["config", "--local", "--get", "core.repositoryFormatVersion"])
    ref_storage = source_git(
        ["config", "--local", "--get", "extensions.refStorage"], expected=(0, 1)
    )
    refs = GIT_DATABASE / "refs"
    reftable = GIT_DATABASE / "reftable"
    if (
        repository_format.stdout != b"0\n" or repository_format.stderr != b""
        or ref_storage.returncode != 1 or ref_storage.stdout != b"" or ref_storage.stderr != b""
        or refs.resolve(strict=True) != refs or refs.is_symlink() or not refs.is_dir()
        or reftable.exists() or reftable.is_symlink()
    ):
        raise PermissionError("H27 source reference storage is not the sealed files backend.")


def decode_and_prevalidate_all() -> dict[str, bytes]:
    if len(EMBEDDED_OBJECTS) != 13:
        raise PermissionError("H27 receiver requires exactly thirteen embedded objects.")
    paths = [str(item.get("path", "")) for item in EMBEDDED_OBJECTS]
    blob_ids = [str(item.get("git_blob_sha1", "")) for item in EMBEDDED_OBJECTS]
    if len(set(paths)) != 13 or len(set(blob_ids)) != 13:
        raise PermissionError("H27 receiver embedded object identities must be unique.")

    decoded: dict[str, bytes] = {}
    # The complete decode phase precedes the complete identity-validation phase.
    for identity in EMBEDDED_OBJECTS:
        value = identity.get("base64")
        if type(value) is not str or "\n" in value or "\r" in value:
            raise PermissionError("H27 embedded base64 must be one canonical literal.")
        try:
            raw = base64.b64decode(value.encode("ascii"), validate=True)
        except (UnicodeEncodeError, ValueError) as exc:
            raise PermissionError("H27 embedded base64 is invalid.") from exc
        if base64.b64encode(raw).decode("ascii") != value:
            raise PermissionError("H27 embedded base64 is not canonical.")
        decoded[str(identity["git_blob_sha1"])] = raw

    if len(decoded) != 13:
        raise PermissionError("H27 receiver did not buffer thirteen unique objects.")
    for identity in EMBEDDED_OBJECTS:
        raw = decoded[str(identity["git_blob_sha1"])]
        if not identity_ok(identity, raw):
            raise PermissionError(f"H27 embedded object identity mismatch: {identity.get('path')}.")
    return decoded


def require_baseline() -> None:
    if source_git(["rev-parse", "--verify", "HEAD"]).stdout != (BASELINE_HEAD + "\n").encode("ascii"):
        raise PermissionError("H27 source baseline HEAD mismatch.")
    if source_git(["symbolic-ref", "-q", "HEAD"]).stdout != (SYMBOLIC_HEAD + "\n").encode("ascii"):
        raise PermissionError("H27 source symbolic HEAD mismatch.")
    if source_worktree_git(["status", "--porcelain=v1", "--untracked-files=all"]).stdout != b"":
        raise PermissionError("H27 source worktree is not clean.")
    if (GIT_DATABASE / "index.lock").exists():
        raise PermissionError("H27 source index lock is present.")


def require_conflicting_process_absent() -> None:
    result = subprocess.run(
        ["ps", "-axo", "pid=,command="],
        check=False,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
    )
    if result.returncode != 0 or result.stderr != b"":
        raise PermissionError("H27 process inventory failed.")
    forbidden = (
        "h27_import_exact_blobs_odb_only_one_shot.py",
        "h27_receive_exact_thirteen_source_odb_blobs_one_shot.py",
        "hash-object -w --stdin",
    )
    for line in result.stdout.decode("utf-8", errors="strict").splitlines():
        fields = line.strip().split(maxsplit=1)
        if len(fields) != 2 or not fields[0].isdigit() or int(fields[0]) == os.getpid():
            continue
        if any(fragment in fields[1] for fragment in forbidden):
            raise PermissionError("H27 conflicting source ODB process is active.")


def regular_refs_snapshot() -> bytes:
    return source_git([
        "for-each-ref", "--sort=refname",
        "--format=%(refname)%00%(objectname)%00%(objecttype)%00",
    ]).stdout


def read_regular_nofollow(path: Path, label: str) -> bytes:
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        metadata = os.fstat(descriptor)
        if not stat.S_ISREG(metadata.st_mode):
            raise PermissionError(f"H27 {label} must be a regular non-symlink file.")
        chunks: list[bytes] = []
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                return b"".join(chunks)
            chunks.append(chunk)
    finally:
        os.close(descriptor)


def root_refs_snapshot() -> tuple[tuple[bytes, bytes], ...]:
    with os.scandir(GIT_DATABASE) as entries:
        selected = [entry for entry in entries if ROOT_REF_PATTERN.fullmatch(entry.name)]
    rows: list[tuple[bytes, bytes]] = []
    for entry in sorted(selected, key=lambda item: item.name.encode("utf-8")):
        metadata = entry.stat(follow_symlinks=False)
        path = GIT_DATABASE / entry.name
        if stat.S_ISLNK(metadata.st_mode) or not stat.S_ISREG(metadata.st_mode) or path.is_symlink():
            raise PermissionError("H27 root ref or pseudoref is not regular and non-symlink.")
        rows.append((entry.name.encode("utf-8"), read_regular_nofollow(path, "root ref")))
    return tuple(rows)


def index_snapshot() -> tuple[bool, bytes]:
    path = GIT_DATABASE / "index"
    if not path.exists():
        return False, b""
    metadata = path.lstat()
    if not stat.S_ISREG(metadata.st_mode) or path.is_symlink():
        raise PermissionError("H27 index must be a regular non-symlink file.")
    return True, read_regular_nofollow(path, "index")


def object_paths_snapshot() -> dict[str, tuple[int, int, int, int, int]]:
    root = GIT_DATABASE / "objects"
    snapshot: dict[str, tuple[int, int, int, int, int]] = {}
    for directory, names, files in os.walk(root, followlinks=False):
        names.sort(key=lambda value: value.encode("utf-8"))
        files.sort(key=lambda value: value.encode("utf-8"))
        directory_path = Path(directory)
        for name in names:
            if (directory_path / name).is_symlink():
                raise PermissionError("H27 source ODB contains a symlink directory.")
        for name in files:
            path = directory_path / name
            metadata = path.lstat()
            if not stat.S_ISREG(metadata.st_mode) or path.is_symlink():
                raise PermissionError("H27 source ODB contains a non-regular entry.")
            relative = path.relative_to(GIT_DATABASE).as_posix()
            snapshot[relative] = (
                metadata.st_dev, metadata.st_ino, metadata.st_mode,
                metadata.st_size, metadata.st_mtime_ns,
            )
    return snapshot


def require_all_objects_absent() -> None:
    for identity in EMBEDDED_OBJECTS:
        oid = str(identity["git_blob_sha1"])
        result = source_git(["cat-file", "-e", oid + "^{blob}"], expected=(0, 1))
        if result.returncode != 1:
            raise PermissionError("H27 source blob must be absent before the first effect.")


def write_exact_objects(decoded: Mapping[str, bytes]) -> None:
    for identity in EMBEDDED_OBJECTS:
        oid = str(identity["git_blob_sha1"])
        result = run_git(
            [
                "git", "--no-replace-objects", f"--git-dir={GIT_DATABASE_TEXT}",
                "hash-object", "-w", "--stdin",
            ],
            stdin=decoded[oid],
        )
        if result.stdout != (oid + "\n").encode("ascii") or result.stderr != b"":
            raise PermissionError("H27 source blob write mismatch; terminal consumed failure.")


def require_all_objects_exact() -> None:
    for identity in EMBEDDED_OBJECTS:
        oid = str(identity["git_blob_sha1"])
        raw = source_git(["cat-file", "blob", oid]).stdout
        if not identity_ok(identity, raw):
            raise PermissionError("H27 terminal source blob identity mismatch.")


def receive_exact_thirteen() -> dict[str, object]:
    require_platform_ack_and_zero_arguments()
    verify_checkout_and_odb_realpaths()
    require_reference_storage_files()
    decoded = decode_and_prevalidate_all()
    require_baseline()
    require_conflicting_process_absent()
    regular_before = regular_refs_snapshot()
    root_before = root_refs_snapshot()
    index_before = index_snapshot()
    objects_before = object_paths_snapshot()

    require_reference_storage_files()
    require_baseline()
    require_conflicting_process_absent()
    if regular_refs_snapshot() != regular_before or root_refs_snapshot() != root_before or index_snapshot() != index_before:
        raise PermissionError("H27 refs or index changed before the first effect.")
    require_all_objects_absent()
    if object_paths_snapshot() != objects_before:
        raise PermissionError("H27 source ODB changed before the first effect.")

    # First irreversible effect. Any interruption or failure from here is
    # terminal and consumed; this receiver contains no retry or cleanup path.
    write_exact_objects(decoded)
    require_all_objects_exact()
    require_reference_storage_files()
    require_baseline()
    require_conflicting_process_absent()
    if regular_refs_snapshot() != regular_before or root_refs_snapshot() != root_before or index_snapshot() != index_before:
        raise PermissionError("H27 terminal refs or index drift; terminal consumed failure.")
    objects_after = object_paths_snapshot()
    expected_new = {
        "objects/" + str(item["git_blob_sha1"])[:2] + "/" + str(item["git_blob_sha1"])[2:]
        for item in EMBEDDED_OBJECTS
    }
    if (
        set(objects_after) != set(objects_before) | expected_new
        or any(objects_after[path] != metadata for path, metadata in objects_before.items())
    ):
        raise PermissionError("H27 unexpected source ODB change; terminal consumed failure.")
    return {
        "status": "H27_SOURCE_ODB_EXACT_THIRTEEN_BLOB_DELIVERY_TERMINAL_SUCCESS",
        "object_count": 13,
        "object_blob_ids": [item["git_blob_sha1"] for item in EMBEDDED_OBJECTS],
        "source_git_database": GIT_DATABASE_TEXT,
        "head_unchanged": True,
        "symbolic_head_unchanged": True,
        "regular_refs_unchanged": True,
        "root_refs_and_pseudorefs_unchanged": True,
        "index_unchanged": True,
        "worktree_clean": True,
        "target_odb_changed": False,
        "import_executed": False,
        "detach_executed": False,
        "downstream_executed": False,
        "science_or_locked_test": False,
    }


if __name__ == "__main__":
    print(json.dumps(receive_exact_thirteen(), ensure_ascii=False, allow_nan=False, separators=(",", ":")))
